import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.ArrayList;
import java.util.Arrays;

public class Main {
    static int L, C;
    static boolean[][] isBlack;
    static boolean[][] isCandidate;
    static int[][] id;
    static ArrayList<Integer>[] adj;
    static int[] match;
    static boolean[] visited;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        if (!st.hasMoreTokens()) return;

        L = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());

        int P = Integer.parseInt(br.readLine().trim());
        isBlack = new boolean[L + 1][C + 1];

        for (int i = 0; i < P; i++) {
            st = new StringTokenizer(br.readLine());
            int r = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            isBlack[r][c] = true;
        }

        isCandidate = new boolean[L + 1][C + 1];
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        int totalCandidates = 0;
        id = new int[L + 1][C + 1];

        for (int r = 1; r <= L; r++) {
            for (int c = 1; c <= C; c++) {
                if (!isBlack[r][c]) {
                    boolean hasBlackNeighbor = false;
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr >= 1 && nr <= L && nc >= 1 && nc <= C && isBlack[nr][nc]) {
                            hasBlackNeighbor = true;
                            break;
                        }
                    }
                    if (hasBlackNeighbor) {
                        isCandidate[r][c] = true;
                        id[r][c] = totalCandidates++;
                    }
                }
            }
        }

        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] graph = new ArrayList[totalCandidates];
        for (int i = 0; i < totalCandidates; i++) {
            graph[i] = new ArrayList<>();
        }
        adj = graph;

        for (int r = 1; r <= L; r++) {
            for (int c = 1; c <= C; c++) {
                if (isCandidate[r][c] && (r + c) % 2 != 0) {
                    int u = id[r][c];
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr >= 1 && nr <= L && nc >= 1 && nc <= C && isCandidate[nr][nc]) {
                            int v = id[nr][nc];
                            adj[u].add(v);
                        }
                    }
                }
            }
        }

        match = new int[totalCandidates];
        Arrays.fill(match, -1);
        visited = new boolean[totalCandidates];

        int maxMatching = 0;
        for (int r = 1; r <= L; r++) {
            for (int c = 1; c <= C; c++) {
                if (isCandidate[r][c] && (r + c) % 2 != 0) {
                    int u = id[r][c];
                    Arrays.fill(visited, false);
                    if (dfs(u)) {
                        maxMatching++;
                    }
                }
            }
        }

        int maxIndependentSet = totalCandidates - maxMatching;
        System.out.println(maxIndependentSet);
    }

    static boolean dfs(int u) {
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                if (match[v] < 0 || dfs(match[v])) {
                    match[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}
